export type ServiceKey =
  | "webDesignDevelopment"
  | "seo"
  | "maintenance"
  | "analytics"
  | "aiSearchOptimization";

const SERVICE_PATHS: Record<ServiceKey, string> = {
  webDesignDevelopment: "/services/web-design-development/",
  seo: "/services/seo/",
  maintenance: "/services/maintenance/",
  analytics: "/services/analytics/",
  aiSearchOptimization: "/services/ai-search-optimization/",
};

const CASE_STUDY_PRIMARY_SERVICE_KEYS: Record<string, ServiceKey> = {
  "reef-cleaning-company": "seo",
  "envirogun": "webDesignDevelopment",
  "chester-court": "webDesignDevelopment",
};

const PRIMARY_CASE_STUDY_BY_SERVICE_KEY: Partial<Record<ServiceKey, string>> = {
  webDesignDevelopment: "chester-court",
  seo: "reef-cleaning-company",
  maintenance: "chester-court",
  analytics: "reef-cleaning-company",
  aiSearchOptimization: "envirogun",
};

export const getServicePathFromKey = (key?: ServiceKey) =>
  key ? SERVICE_PATHS[key] : undefined;

export const getServiceKeyFromPath = (path?: string): ServiceKey | undefined =>
  (Object.entries(SERVICE_PATHS).find(([, value]) => value === path)?.[0] as
    | ServiceKey
    | undefined);

export const getCaseStudyPrimaryServiceKey = (slug: string) =>
  CASE_STUDY_PRIMARY_SERVICE_KEYS[slug];

export const getCaseStudyPrimaryServicePath = (slug: string) =>
  getServicePathFromKey(getCaseStudyPrimaryServiceKey(slug));

export const getPrimaryCaseStudySlugForServicePath = (path?: string) => {
  const serviceKey = getServiceKeyFromPath(path);
  return serviceKey ? PRIMARY_CASE_STUDY_BY_SERVICE_KEY[serviceKey] : undefined;
};

export const getPrimaryCaseStudyPathForServicePath = (path?: string) => {
  const slug = getPrimaryCaseStudySlugForServicePath(path);
  return slug ? `/portfolio/case-studies/${slug}/` : undefined;
};
